import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import type {ChatSession} from '../types/session.js';

// Contract: a real lifecycle hook rejects before the provider is called.
it('reports a thrown string with its cause and preserves the caller rejection', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failures: Error[] = [];
  const callOrder: string[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => {
          throw 'hook rejected';
        },
        onError: async (_session, error) => {
          failures.push(error);
          callOrder.push('onError');
        },
        afterSession: async () => {
          callOrder.push('afterSession');
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({
    rejection,
    count: failures.length,
    isError: failures[0] instanceof Error,
    message: failures[0]?.message,
    cause: failures[0]?.cause,
    callOrder,
  }).toEqual({
    rejection: 'hook rejected',
    count: 1,
    isError: true,
    message: 'hook rejected',
    cause: 'hook rejected',
    callOrder: ['onError', 'afterSession'],
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"

